mapper.select:
select k.item_id as itemId, k.keyword as keyword
from sorting_item_keyword k
join sorting_item i on i.id = k.item_id
where k.language_code = #{languageCode}
  and i.municipality_id = #{municipalityId}
union all

select e.item_id as itemId, e.example as keyword
from sorting_item_example e
join sorting_item i on i.id = e.item_id
where e.language_code = #{languageCode}
  and i.municipality_id = #{municipalityId}
order by itemId, keyword
